		   MAX_NO = #{updateMaxNo}


		  ,STOCK_NO = CONCAT(@STOCK_SIGN, 


		  ,STOCK_NO = CONCAT(@STOCK_SIGN, @DATE1, 


		  ,STOCK_NO = CONCAT(SUBSTRING(#{entBusinessCode}, 7, 2), '-', @STOCK_SIGN, @DATE1, '-', 


		  	REPLICATE('0', #{stockSeqLength} - LEN(CONVERT(VARCHAR, #{updateMaxNo}))) + CONVERT(VARCHAR, #{updateMaxNo}))

		  ,UPDATE_USER_ID = #{updateUserId}
