DECLARE @RES_STOCK_NO VARCHAR(100);
DECLARE @DATE1 VARCHAR(20);
DECLARE @DATE2 VARCHAR(20) = CONVERT(VARCHAR(10), DATEADD(HOUR, ${gmtTime}, GETDATE()), 112);
DECLARE @SEQNO VARCHAR(20) = #{seqNo};	



IF #{dateLength} != ''
	SET @DATE1 = SUBSTRING(CONVERT(VARCHAR(10), GETDATE(), CONVERT(INT, #{stockDateFormat})), 1, CONVERT(INT, #{dateLength}));
ELSE
	SET @DATE1 = CONVERT(VARCHAR(10), GETDATE(), CONVERT(INT, #{stockDateFormat}));


SET @DATE1 = #{stockDateStr};


IF #{dateLength} != ''
	SET @DATE1 = SUBSTRING(CONVERT(VARCHAR(10), GETDATE(), 12), 1, CONVERT(INT, #{dateLength}));
ELSE
	SET @DATE1 = CONVERT(VARCHAR(10), GETDATE(), 12);







	DECLARE @STOCK_SIGN VARCHAR(20) = CONCAT(@DATE1, #{stockSign});


	DECLARE @STOCK_SIGN VARCHAR(20) = CONCAT(#{stockSign}, @DATE1);


	DECLARE @STOCK_SIGN VARCHAR(20) = CONCAT(#{stockSign}, @DATE1, '-');




	DECLARE @STOCK_SIGN VARCHAR(20) = #{stockSign};




SET @STOCK_SIGN = CONCAT(@STOCK_SIGN, #{appendStockSign})

