/* CommonMapper.selectExcelOrderCount : 포멧별 엑셀 다운로드시 필요한 데이터 count */ SELECT COUNT(*) FROM TB_ECM_OD od LEFT JOIN TB_ECM_OD_ADDITIONAL ad ON ad.OD_JOB_NO = od.OD_JOB_NO
