/* CommonMapper.selectHeadEntBusinessInfo : 대표사업장정보조회  */
SELECT TOP 1 ENT_BUSINESS_CODE
FROM TB_SMS_ENT_BUSINESS
WHERE ENT_CODE = #{srchEntCode}
AND HEAD_BUSINESS_YN = 'Y'

/* 하우스비엘번호스탁 odJobNo : ${odJobNo} / createCnt : ${createCnt} */
DECLARE @DELIVERY_CODE VARCHAR(20) = #{deliveryCode};
