/* CommonMapper.selectLastPodInfo : POD테이블의 lastPod정보 조회 */
	SELECT TOP 1
		 A.POD_STATUS
		,A.POD_DATE
		,A.POD_TIME
		,CASE WHEN A.POD_DATE IS NULL THEN NULL ELSE CONCAT(A.POD_DATE, ' ' , A.POD_TIME) END AS POD_DATE_TIME
 	FROM(
 		SELECT POD_STATUS, POD_DATE, POD_TIME FROM TB_ECM_POD_01 WHERE OD_JOB_NO = #{OD_JOB_NO}
 		UNION ALL
 		SELECT POD_STATUS, POD_DATE, POD_TIME FROM TB_ECM_POD_02 WHERE OD_JOB_NO = #{OD_JOB_NO}
 		UNION ALL
 		SELECT POD_STATUS, POD_DATE, POD_TIME FROM TB_ECM_POD_03 WHERE OD_JOB_NO = #{OD_JOB_NO}
 		UNION ALL
 		SELECT POD_STATUS, POD_DATE, POD_TIME FROM TB_ECM_POD_04 WHERE OD_JOB_NO = #{OD_JOB_NO}
 	) A
 	ORDER BY A.POD_STATUS DESC

/* CommonMapper.selectManifestLastPodInfo : POD테이블의 lastPod정보 조회 */
	SELECT TOP 1
		 A.POD_STATUS
		,A.POD_DATE
		,A.POD_TIME
		,CASE WHEN A.POD_DATE IS NULL THEN NULL ELSE CONCAT(A.POD_DATE, ' ' , A.POD_TIME) END AS POD_DATE_TIME
 	FROM(
 		SELECT POD_STATUS, POD_DATE, POD_TIME FROM TB_ECM_POD_01 WHERE OD_JOB_NO = #{OD_JOB_NO}
 		UNION ALL
 		SELECT POD_STATUS, POD_DATE, POD_TIME FROM TB_ECM_POD_02 WHERE OD_JOB_NO = #{OD_JOB_NO}
 	) A
 	ORDER BY A.POD_STATUS DESC

/* CommonMapper.getDomesticCodeList : Order List(Detail) */
	SELECT
		 CODE
		,NAME_DEFAULT AS NAME
	FROM TB_SMS_CODE_DETAIL
	WHERE ENT_CODE = #{entCode}
	AND GROUP_CODE = #{groupCode}

	AND ETC4 = #{strFixedAMS_AMS_CountryCode}

/* CommonMapper.selectExchangeRate2 : 환율조회 */
	SELECT ISNULL(${exrateType}, 0) AS EXCHANGE_RATE
	FROM TB_SMS_EXCHANGE_RATE
	WHERE ENT_CODE = #{srchEntCode}
	AND ENT_BUSINESS_CODE = #{entBusinessCode}
	AND EXRATE_DATE = CONVERT(DATE, #{srchDate}, ${srchDateFormat})
	AND CURRENCY_CODE = #{srchCurrencyCode}

/* CommonMapper.selectChkDupBlNo : 비엘번호 중복체크 */
	SELECT COUNT(OD_JOB_NO) AS CNT
	FROM TB_ECM_OD
	WHERE ENT_CODE = #{entCode}
	AND BL_TYPE_MH = #{blTypeMh}


	AND MBL_NO = LTRIM(RTRIM(REPLACE(#{blNo},char(9),'')))

	AND BOUND = #{bound}
	AND BOUND_TYPE = #{boundType}



	AND HBL_NO = LTRIM(RTRIM(REPLACE(#{blNo},char(9),'')))


		AND MASTER_OD_JOB_NO = #{masterOdJobNo}


		AND CONSOL_YN = 'N'





	AND OD_JOB_NO != #{odJobNo}



	AND ISNULL(HSN, '') = #{hsn}

/* CommonMapper.selectCustomerInfoList : 거래처정보조회 */
	SELECT
		 CUSTOMER_CODE
	FROM TB_SMS_CUSTOMER
	WHERE ENT_CODE = #{entCode}
	AND CUSTOMER_LEVEL = #{customerLevel}

/* CommonMapper.selectCodeName : 코드명 조회  */


	SELECT

		 MAX(CASE CODE WHEN #{item} THEN NAME_${userLanguage} END) AS CODE_NAME_${item}

	FROM TB_SMS_CODE_DETAIL
	WHERE ENT_CODE = #{entCode}
	AND GROUP_CODE = #{srchGroupCode}
	AND CODE IN(#{item})
	GROUP BY ENT_CODE


	SELECT NAME_${userLanguage} AS CODE_NAME
	FROM TB_SMS_CODE_DETAIL
	WHERE ENT_CODE = #{entCode}
	AND GROUP_CODE = #{srchGroupCode}
	AND CODE = #{srchCode}

/* CommonMapper.selectSimpleDocSendYn : 통관목록신고여부 */ SELECT MAX(CASE WHEN ISNULL(ad.SIMPLE_EDI_STATUS, '') NOT IN ('', 'ERROR') THEN 'Y' END) AS SEND_YN ,MAX(od.OD_JOB_NO) AS OD_JOB_NO ,MAX(od.FINISH_YN) AS FINISH_YN
,MAX(CASE WHEN ISNULL(simpleDocNoAd.SIMPLE_EDI_STATUS, '') NOT IN ('', 'ERROR') THEN 'Y' END) AS SIMPLE_DOC_NO_SEND_YN
,COUNT(DISTINCT CASE WHEN ad.SIMPLE_DOC_NO LIKE 'AE%' THEN ad.SIMPLE_DOC_NO END) AS AE_DOC_CNT ,MAX(CASE WHEN ad.SIMPLE_DOC_NO LIKE 'AE%' THEN ad.SIMPLE_DOC_NO END) AS AE_DOC_NO ,COUNT(DISTINCT CASE WHEN ad.SIMPLE_DOC_NO LIKE 'AD%' THEN ad.SIMPLE_DOC_NO END) AS AD_DOC_CNT ,MAX(CASE WHEN ad.SIMPLE_DOC_NO LIKE 'AD%' THEN ad.SIMPLE_DOC_NO END) AS AD_DOC_NO
FROM TB_ECM_OD od INNER JOIN TB_ECM_OD_ADDITIONAL ad ON ad.OD_JOB_NO = od.OD_JOB_NO
LEFT JOIN TB_ECM_OD_ADDITIONAL simpleDocNoAd ON simpleDocNoAd.OD_JOB_NO = od.OD_JOB_NO AND simpleDocNoAd.SIMPLE_DOC_NO = #{simpleDocNo}
WHERE od.MASTER_OD_JOB_NO = #{masterOdJobNo}
FROM TB_ECM_OD od2 INNER JOIN TB_ECM_OD od ON od.MASTER_OD_JOB_NO = od2.MASTER_OD_JOB_NO INNER JOIN TB_ECM_OD_ADDITIONAL ad ON ad.OD_JOB_NO = od.OD_JOB_NO
LEFT JOIN TB_ECM_OD_ADDITIONAL simpleDocNoAd ON simpleDocNoAd.OD_JOB_NO = od.OD_JOB_NO AND simpleDocNoAd.SIMPLE_DOC_NO = #{simpleDocNo}
WHERE od2.OD_JOB_NO = #{odJobNo}

