	INSERT INTO ${podTableName}(
		   POD_JOB_NO
		  ,ENT_CODE
		  ,OD_JOB_NO
		  ,POD_STATUS
		  ,POD_DATE
		  ,POD_TIME
		  ,BL_NO
		  ,REGISTER_USER_ID
		  ,REGISTER_DATE_TIME
		  ,UPDATE_USER_ID
		  ,UPDATE_DATE_TIME
	)VALUES(
		   #{podJobNo}
		  ,#{entCode}
		  ,#{odJobNo}
		  ,#{podStatus}


