/* CommonMapper."updatePod" : 전자상거래 POD 저장 */
	UPDATE TB_ECM_POD SET
		   UPDATE_USER_ID = #{updateUserId}
		  ,UPDATE_DATE_TIME = DATEADD(HOUR, ${gmtTime}, GETDATE())


		  ,POD_DATE = CONVERT(DATE, #{podDate}, ${dateFormat})


		  ,POD_DATE = DATEADD(HOUR, ${gmtTime}, GETDATE())




		  ,POD_TIME = #{podTime}


		  ,POD_TIME = CONVERT(VARCHAR(5), DATEADD(HOUR, ${gmtTime}, GETDATE()), 108)


	WHERE OD_JOB_NO = #{odJobNo}
	AND POD_STATUS = #{podStatus};

	UPDATE ${podTableName} SET
		   UPDATE_USER_ID = #{updateUserId}
		  ,UPDATE_DATE_TIME = DATEADD(HOUR, ${gmtTime}, GETDATE())


		  ,POD_DATE = CONVERT(DATE, #{podDate}, ${dateFormat})


		  ,POD_DATE = DATEADD(HOUR, ${gmtTime}, GETDATE())




		  ,POD_TIME = #{podTime}


		  ,POD_TIME = CONVERT(VARCHAR(5), DATEADD(HOUR, ${gmtTime}, GETDATE()), 108)


	WHERE OD_JOB_NO = #{odJobNo}
	AND POD_STATUS = #{podStatus};

