/* CommonMapper.selectSimpleDocNoCount */
	SELECT COUNT(OD_JOB_NO) AS CNT
	FROM TB_ECM_OD_ADDITIONAL
	WHERE SIMPLE_DOC_NO = #{simpleDocNo}

	AND ISNULL(SIMPLE_EDI_STATUS, '') NOT IN ('', 'ERROR')

/* CommonMapper.getOdJobNo : 하우스번호, 오더번호로 스캔시 OD_JOB_NO 조회 */ SELECT TOP 1 od.OD_JOB_NO, odAdd.PRINT_YN, odAdd.PRINT_DATE ,od.CONSIGNEE_NAME_LOC ,od.CONSIGNEE_ADDRESS_LOC ,od.CONSIGNEE_ZIPCODE ,od.PIECES, od.MULTI_YN FROM TB_ECM_OD od LEFT JOIN TB_ECM_OD_ADDITIONAL odAdd ON od.OD_JOB_NO = odAdd.OD_JOB_NO WHERE od.ENT_CODE = #{srchEntCode}
AND ${srchScanNoType} IN (#{item})
AND ${srchScanNoType} = #{srchScanNo}
AND od.BOUND = 'AIR' AND od.BOUND_TYPE = 'EXP' AND od.BOUND = 'AIR' AND od.BOUND_TYPE = 'IMP' AND od.BOUND = 'SEA' AND od.BOUND_TYPE = 'EXP' AND od.BOUND = 'SEA' AND od.BOUND_TYPE = 'IMP'
ORDER BY od.PO_DATE DESC

